import type { Server } from 'socket.io';

export const ROOM = 'room-1';
export const WORD = 'giraffe';
export const LABELS = ['A', 'B', 'C'] as const;

export type Label = (typeof LABELS)[number];

export interface StrokeSegment {
  id: number;
  points: Array<[x: number, y: number]>;
  end?: true;
}

export interface JoinResult {
  accepted: boolean;
  room: string;
}

export interface ChatMessage {
  from: Label;
  text: string;
}

export interface RoundResult {
  winner: Label;
  word: string;
}

export interface ClientToServerEvents {
  join: (room: string, acknowledge: (result: JoinResult) => void) => void;
  stroke: (segment: StrokeSegment) => void;
  chat: (text: string) => void;
  guess: (text: string, acknowledge: (correct: boolean) => void) => void;
}

export interface ServerToClientEvents {
  stroke: (segment: StrokeSegment) => void;
  chat: (message: ChatMessage) => void;
  correct: (result: { word: string }) => void;
  announce: (result: RoundResult) => void;
}

export type DrawingGameServer = Server<ClientToServerEvents, ServerToClientEvents>;

function isLabel(value: unknown): value is Label {
  return value === 'A' || value === 'B' || value === 'C';
}

/** The application handlers used unchanged by Real Socket.IO and Smocket. */
export function registerDrawingGameHandlers(io: DrawingGameServer): void {
  io.on('connection', (socket) => {
    const claimedLabel = socket.handshake.auth.label;
    if (!isLabel(claimedLabel)) {
      socket.disconnect(true);
      return;
    }

    const label = claimedLabel;
    // [snippet:start room-join]
    socket.on('join', async (room, acknowledge) => {
      if (room !== ROOM) {
        acknowledge({ accepted: false, room });
        return;
      }
      await socket.join(room);
      acknowledge({ accepted: true, room });
    });
    // [snippet:end room-join]

    // [snippet:start drawing-server-handler]
    socket.on('stroke', (segment) => {
      socket.to(ROOM).emit('stroke', segment);
    });
    // [snippet:end drawing-server-handler]

    // [snippet:start chat-guess-server-handler]
    socket.on('chat', (text) => {
      io.to(ROOM).emit('chat', { from: label, text });
    });

    socket.on('guess', (text, acknowledge) => {
      // [snippet:start acknowledgement]
      const correct = text === WORD;
      acknowledge(correct);
      // [snippet:end acknowledgement]

      if (!correct) {
        io.to(ROOM).emit('chat', { from: label, text });
        return;
      }

      // [snippet:start targeted-correct]
      io.to(socket.id).emit('correct', { word: WORD });
      // [snippet:end targeted-correct]
      // [snippet:start room-announce]
      io.to(ROOM).emit('announce', { winner: label, word: WORD });
      // [snippet:end room-announce]
    });
    // [snippet:end chat-guess-server-handler]
  });
}

import { io, type Socket } from 'socket.io-client';
import {
  ROOM,
  type ChatMessage,
  type ClientToServerEvents,
  type JoinResult,
  type Label,
  type RoundResult,
  type ServerToClientEvents,
  type StrokeSegment,
} from './application.js';

export type DrawingGameClient = Socket<ServerToClientEvents, ClientToServerEvents>;

/** This import and constructor stay unchanged when the target becomes Smocket. */
export function createDrawingGameClient(url: string, label: Label): DrawingGameClient {
  return io(url, {
    auth: { label },
    forceNew: true,
  });
}

export function waitForConnection(client: DrawingGameClient): Promise<void> {
  if (client.connected) return Promise.resolve();

  return new Promise((resolve, reject) => {
    const connected = () => {
      client.off('connect_error', failed);
      resolve();
    };
    const failed = (error: Error) => {
      client.off('connect', connected);
      reject(error);
    };

    client.once('connect', connected);
    client.once('connect_error', failed);
  });
}

export function joinGame(client: DrawingGameClient): Promise<JoinResult> {
  return new Promise((resolve) => client.emit('join', ROOM, resolve));
}

// [snippet:start drawing-client]
export function receiveStrokes(
  client: DrawingGameClient,
  receive: (segment: StrokeSegment) => void,
): void {
  client.on('stroke', receive);
}

export function sendStroke(client: DrawingGameClient, segment: StrokeSegment): void {
  client.emit('stroke', segment);
}
// [snippet:end drawing-client]

// [snippet:start chat-guess-client]
export function receiveChat(client: DrawingGameClient, receive: (message: ChatMessage) => void) {
  client.on('chat', receive);
}

export function receiveCorrect(client: DrawingGameClient, receive: (word: string) => void) {
  client.on('correct', ({ word }) => receive(word));
}

export function receiveAnnouncement(
  client: DrawingGameClient,
  receive: (result: RoundResult) => void,
) {
  client.on('announce', receive);
}

export function submitGuess(client: DrawingGameClient, text: string): Promise<boolean> {
  return new Promise((resolve) => client.emit('guess', text, resolve));
}
// [snippet:end chat-guess-client]

